            if (b.N != A.Rows) throw new ArgumentException("idr: b.N must equal A.Rows");
            if (x.N != A.Rows) throw new ArgumentException("idr: x.N must equal A.Rows");
            if (s < 1) throw new ArgumentException("idr: s must be >= 1");
            if (maxIter < 1) throw new ArgumentException("idr: maxIter must be >= 1");

            int n = A.Rows;

            float bb = Blas.dot(b, b);
            if (bb == (float)0)
            {
                x.CopyFrom(in b);
                return MakeSolveInfo(IterativeSolveStatus.Converged, 0, (float)0);
            }
            float threshold = tol * tol * bb;

            // Workspace (Temp). P is the fixed shadow space (deterministic, from seed); G/U are the s
            // search-space vectors (start at zero); Q/V (and VHat, only for a real preconditioner) are
            // scratch; Msys/f/c are the small s×s system and its right-hand side / solution.
            var P = new UnsafeList<floatN>(s, Allocator.Temp);
            var G = new UnsafeList<floatN>(s, Allocator.Temp);
            var U = new UnsafeList<floatN>(s, Allocator.Temp);
            for (int i = 0; i < s; i++)
            {
                P.Add(new floatN(n, Allocator.Temp, true));
                G.Add(new floatN(n));
                U.Add(new floatN(n));
            }

            var rng = new Unity.Mathematics.Random(seed == 0 ? 0x9E3779B1u : seed);
            for (int i = 0; i < s; i++)
            {
                floatN Pi = P[i];
                for (int col = 0; col < n; col++) Pi[col] = rng.NextFloat();
            }

            var R = new floatN(n);
            var V = new floatN(n);
            var Q = new floatN(n);
            floatN VHat = default;
            if (!M.IsIdentity) VHat = new floatN(n);

            var Msys = new floatMxN(s, s, Allocator.Temp, false);
            for (int i = 0; i < s; i++) Msys[i, i] = (float)1;
            var f = new floatN(s);
            var c = new floatN(s);

            // R = b - A x
            A.Apply(in x, ref V);
            R.CopyFrom(in b);
            R.addScaledInPlace((float)(-1), V);

            float rr = Blas.dot(R, R);
            float om = (float)1;
            int iter = 0;

            IterativeSolveStatus status = IterativeSolveStatus.MaxIterations;
            bool done = false;
            if (rr <= threshold) { status = IterativeSolveStatus.Converged; done = true; }

            while (iter < maxIter && !done)
            {
                for (int i = 0; i < s; i++) f[i] = Blas.dot(P[i], R);

                for (int k = 0; k < s && iter < maxIter; k++)
